```file apiwrap/client.py
"""HTTP client with retries."""
import time


class Transient(Exception):
    pass


_IDEMPOTENT_METHODS = frozenset({"GET", "HEAD", "PUT", "DELETE"})


class Client:
    def __init__(self, transport, backoff=0.01):
        self.transport = transport
        self.backoff = backoff

    def call(self, method, path, body=None, timeout=1.0, attempts=3, idempotency_key=None):
        headers = {}
        if idempotency_key is not None:
            headers["Idempotency-Key"] = idempotency_key

        upper = method.upper()
        can_retry = upper in _IDEMPOTENT_METHODS or (upper == "POST" and idempotency_key is not None)

        last_exc = None
        for i in range(attempts):
            if i:
                time.sleep(self.backoff * 2 ** (i - 1))
            try:
                status, resp_body = self.transport(method, path, body, headers)
                return (status, resp_body)
            except Transient as exc:
                last_exc = exc
                if not can_retry:
                    raise
                continue

        raise last_exc
