"""In-memory session storage backend."""
import time

from .errors import UnknownSession


class MemoryStore:
    def __init__(self, ttl=None, clock=None):
        self.ttl = ttl
        self._clock = clock if clock is not None else time.monotonic
        self._data = {}

    def _expired(self, sid):
        if self.ttl is None:
            return False
        return self._clock() - self._data[sid][1] >= self.ttl

    def get(self, sid):
        if sid not in self._data or self._expired(sid):
            raise UnknownSession(sid)
        return self._data[sid][0]

    def set(self, sid, value):
        self._data[sid] = [value, self._clock()]

    def delete(self, sid):
        self._data.pop(sid, None)

    def touch(self, sid):
        self._data[sid][1] = self._clock()

    def clear(self):
        self._data.clear()

    def keys(self):
        return sorted(
            (sid for sid in self._data if not self._expired(sid)),
            key=lambda sid: (self._data[sid][1], sid),
        )
