from decimal import Decimal, ROUND_HALF_UP, ROUND_FLOOR


class CurrencyMismatch(Exception):
    pass


class Money:
    def __init__(self, amount, currency='USD'):
        self.currency = currency
        self.cents = int(
            (Decimal(str(amount)) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        )

    @classmethod
    def _from_cents(cls, cents, currency):
        obj = cls(0, currency)
        obj.cents = cents
        return obj

    def _check_currency(self, other):
        if self.currency != other.currency:
            raise CurrencyMismatch(
                f"Cannot operate on {self.currency} and {other.currency}"
            )

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self.cents + other.cents, self.currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self.cents - other.cents, self.currency)

    def __mul__(self, other):
        if isinstance(other, Money):
            raise TypeError("Cannot multiply Money by Money")
        if not isinstance(other, (int, Decimal, float)):
            return NotImplemented
        new_cents = int(
            (Decimal(self.cents) * Decimal(str(other))).quantize(
                Decimal('1'), rounding=ROUND_HALF_UP
            )
        )
        return Money._from_cents(new_cents, self.currency)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __neg__(self):
        return Money._from_cents(-self.cents, self.currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents and self.currency == other.currency

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents < other.cents

    def __le__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents <= other.cents

    def __gt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents > other.cents

    def __ge__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self.cents >= other.cents

    def __hash__(self):
        return hash((self.cents, self.currency))

    def __repr__(self):
        return f"Money({self.cents / 100}, {self.currency!r})"

    def format(self):
        if self.cents < 0:
            sign = '-'
            abs_cents = -self.cents
        else:
            sign = ''
            abs_cents = self.cents
        dollars = abs_cents // 100
        cents_part = abs_cents % 100
        return f"{sign}${dollars}.{cents_part:02d}"

    def allocate(self, pairs):
        pairs = list(pairs)
        for key, weight in pairs:
            if weight <= 0:
                raise ValueError(
                    f"Weight must be positive, got {weight!r} for key {key!r}"
                )

        if self.cents == 0:
            return {key: Money(0, self.currency) for key, weight in pairs}

        total_weight = sum(weight for _, weight in pairs)
        total_cents = self.cents

        bases = []
        for key, weight in pairs:
            exact = Decimal(total_cents) * Decimal(str(weight)) / Decimal(str(total_weight))
            bases.append(int(exact.to_integral_value(rounding=ROUND_FLOOR)))

        remainder = total_cents - sum(bases)

        # Sort indices by weight descending; ties broken by original order (earlier key first)
        order = sorted(range(len(pairs)), key=lambda i: (-pairs[i][1], i))

        step = 1 if remainder > 0 else -1
        for i in range(abs(remainder)):
            idx = order[i % len(order)]
            bases[idx] += step

        return {
            pairs[i][0]: Money._from_cents(bases[i], self.currency)
            for i in range(len(pairs))
        }
