"""Migration runner."""

import heapq

from .errors import MigrationError


def plan(migrations):
    names = [m['name'] for m in migrations]
    if len(names) != len(set(names)):
        raise MigrationError("Duplicate migration names")

    name_set = set(names)
    for m in migrations:
        for dep in m.get('deps', []):
            if dep not in name_set:
                raise MigrationError(f"Missing dependency: {dep}")

    in_degree = {name: 0 for name in names}
    dependents = {name: [] for name in names}

    for m in migrations:
        for dep in m.get('deps', []):
            in_degree[m['name']] += 1
            dependents[dep].append(m['name'])

    heap = [name for name, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(names):
        raise MigrationError("Dependency cycle detected")

    return result


def applied(db):
    return set(db.applied_migrations)


def migrate(conn, migrations, db, dry_run=False):
    order = plan(migrations)
    already = applied(db)
    to_apply = [name for name in order if name not in already]

    if dry_run:
        return to_apply

    mig_map = {m['name']: m for m in migrations}

    applied_this_call = []
    try:
        for name in to_apply:
            mig_map[name]['up'](conn)
            db.record(name)
            applied_this_call.append(name)
    except Exception:
        for name in reversed(applied_this_call):
            mig_map[name]['down'](conn)
            db.applied_migrations.remove(name)
        raise

    return applied_this_call


def rollback_last(conn, migrations, db):
    if not db.applied_migrations:
        return None

    name = db.applied_migrations[-1]
    mig_map = {m['name']: m for m in migrations}

    if name not in mig_map:
        raise MigrationError(f"Migration not found: {name}")

    mig_map[name]['down'](conn)
    db.applied_migrations.remove(name)
    return name
