import time


class Cache:
    def __init__(self, default_ttl=None, get_clock=None):
        self.default_ttl = default_ttl
        self._get_clock = get_clock if get_clock is not None else time.monotonic
        self._data = {}  # key -> (value, expiry_or_None)

    def put(self, key, value, ttl=None):
        effective_ttl = ttl if ttl is not None else self.default_ttl
        if effective_ttl is None:
            expiry = None
        else:
            expiry = self._get_clock() + effective_ttl
        self._data[key] = (value, expiry)

    def _is_expired(self, key):
        if key not in self._data:
            return True
        _, expiry = self._data[key]
        if expiry is None:
            return False
        return self._get_clock() >= expiry

    def get(self, key):
        if key not in self._data:
            return None
        value, expiry = self._data[key]
        if expiry is not None and self._get_clock() >= expiry:
            del self._data[key]
            return None
        return value

    def get_or_set(self, key, factory, ttl=None):
        value = self.get(key)
        if value is not None:
            return value
        value = factory()
        self.put(key, value, ttl)
        return value

    def delete(self, key):
        if key in self._data:
            del self._data[key]
            return True
        return False

    def __len__(self):
        return sum(1 for key in self._data if not self._is_expired(key))

    def __contains__(self, key):
        return key in self._data and not self._is_expired(key)

    def purge(self):
        expired = [key for key in self._data if self._is_expired(key)]
        for key in expired:
            del self._data[key]
