    return out


def drain(source):
    try:
        for item in source:
            yield item
    finally:
        source.close()


def close_all(sources):
    errors = []
    for source in sources:
        try:
            source.close()
        except Exception as exc:
            errors.append(exc)
    if errors:
        messages = "; ".join(str(e) for e in errors)
        raise DrainError(messages, items=[], cause=errors[0])
