"""Parallel-capable state machine."""


class UnknownState(Exception):
    pass


class GuardFailed(Exception):
    pass


class NotParallel(Exception):
    pass


class Machine:
    def __init__(self, initial, states, on_transition=None):
        self.initial = initial
        self.states = states
        self.state = initial
        self.history = [initial]
        self.on_transition = on_transition
        self._parallel_regions = {}
        self._current_branch = None
        self._current_region = None
        if self._is_parallel(initial):
            self._current_region = initial
            self._parallel_regions[initial] = {
                'branches': list(self.states[initial]['parallel']),
                'completed': set(),
            }

    def _is_parallel(self, name):
        if name not in self.states:
            return False
        defn = self.states[name]
        return isinstance(defn, dict) and 'parallel' in defn

    def _get_transitions(self, state_name):
        if state_name not in self.states:
            return []
        defn = self.states[state_name]
        if isinstance(defn, dict) and 'parallel' in defn:
            return []
        if isinstance(defn, list):
            return defn
        return []

    def _get_reachable(self, state_name):
        reachable = set()
        for t in self._get_transitions(state_name):
            if isinstance(t, dict):
                reachable.add(t['to'])
            else:
                reachable.add(t)
        if self._current_region is not None:
            region_def = self.states.get(self._current_region)
            if region_def and isinstance(region_def, dict) and 'parallel' in region_def:
                for branch in region_def['parallel']:
                    reachable.add(branch)
        return reachable

    def _find_transition(self, state_name, target):
        for t in self._get_transitions(state_name):
            if isinstance(t, dict):
                if t['to'] == target:
                    return t
            else:
                if t == target:
                    return {'to': target}
        return None

    def go(self, target, **ctx):
        if target not in self.states:
            raise UnknownState(target)

        reachable = self._get_reachable(self.state)
        if target not in reachable:
            raise UnknownState(target)

        transition = self._find_transition(self.state, target)
        if transition is None:
            transition = {'to': target}

        guard = transition.get('guard')
        if guard is not None:
            if not guard(**ctx):
                raise GuardFailed(f"Guard failed: {self.state} -> {target}")

        src = self.state
        self.state = target
        self.history.append(target)

        if self._is_parallel(target):
            self._current_region = target
            self._parallel_regions[target] = {
                'branches': list(self.states[target]['parallel']),
                'completed': set(),
            }
            self._current_branch = None
        elif (self._current_region is not None
              and target in self.states[self._current_region]['parallel']):
            self._current_branch = target
            self._parallel_regions[self._current_region]['completed'].discard(target)

        if self._current_branch is not None and not self._is_parallel(target):
            if len(self._get_transitions(target)) == 0:
                self._parallel_regions[self._current_region]['completed'].add(
                    self._current_branch)
                self._current_branch = None
                region_info = self._parallel_regions[self._current_region]
                if len(region_info['completed']) == len(region_info['branches']):
                    self._current_region = None

        action = transition.get('action')
        if action is not None:
            try:
                result = action(target)
            except Exception:
                self.state = src
                self.history.pop()
                raise
            if result is not None:
                if self.on_transition:
                    self.on_transition(src, target)
                return result

        if self.on_transition:
            self.on_transition(src, target)

        return target

    def join(self, name):
        if name not in self.states:
            raise NotParallel(name)
        if not self._is_parallel(name):
            raise NotParallel(name)
        if name not in self._parallel_regions:
            return False
        region_info = self._parallel_regions[name]
        return len(region_info['completed']) == len(region_info['branches'])
